// Productivity Card Component
const ProductivityCard = ({ employee, onClick, productivityData }) => {
  const [displayData, setDisplayData] = useState({
    travelHours: 0,
    restHours: 0,
    workHours: 0,
    productivityScore: 0,
    locationsVisited: 0,
  });

  useEffect(() => {
    if (productivityData) {
      // Parse time strings to hours
      const parseTimeToHours = (timeStr) => {
        if (!timeStr) return 0;
        const parts = timeStr.split(':');
        if (parts.length >= 2) {
          return parseInt(parts[0]) + (parseInt(parts[1]) / 60);
        }
        return 0;
      };

      const movingHrs = parseTimeToHours(productivityData.movingHrs || "00:00");
      const notmovingHrs = parseTimeToHours(productivityData.notmovingHrs || "00:00");
      const totalWorkingHours = parseTimeToHours(productivityData.totalWorkingHours || "00:00");

      const productivityScore = productivityData.efficiencyScore || 0;
      const locationsVisited = productivityData.locationsVisited || Math.floor((productivityData.totalKMMoved || 0) / 5) + 1;

      setDisplayData({
        travelHours: movingHrs.toFixed(1),
        restHours: notmovingHrs.toFixed(1),
        workHours: totalWorkingHours.toFixed(1),
        productivityScore,
        locationsVisited,
      });
    } else {
      // No productivity data available - show zeros
      setDisplayData({
        travelHours: '0.0',
        restHours: '0.0',
        workHours: '0.0',
        productivityScore: 0,
        locationsVisited: 0,
      });
    }
  }, [employee, productivityData]);

  return (
    <Card
      className="mb-3 shadow-sm"
      style={{ cursor: 'pointer' }}
      onClick={onClick}
    >
      <Card.Body>
        <Row className="align-items-center">
          <Col xs={3} className="text-center">
            <div className="rounded-circle bg-light p-3 d-inline-block">
              <FaUser size={24} className="text-primary" />
            </div>
          </Col>
          <Col xs={9}>
            <h6 className="mb-1">{employee.name}</h6>
            <small className="text-muted d-block mb-2">
              {employee.employeeId} • {employee.branch}
            </small>

            <div className="d-flex justify-content-between small mb-2">
              <span>
                <FaWalking className="me-1" /> {displayData.travelHours}h
              </span>
              <span>
                <FaBed className="me-1" /> {displayData.restHours}h
              </span>
              <span>
                <FaChartBar className="me-1" /> {displayData.workHours}h
              </span>
            </div>

            <div className="mb-2">
              <div className="d-flex justify-content-between mb-1">
                <small>Productivity</small>
                <small>{displayData.productivityScore}%</small>
              </div>
              <ProgressBar
                now={displayData.productivityScore}
                variant={
                  displayData.productivityScore > 80
                    ? 'success'
                    : displayData.productivityScore > 60
                      ? 'warning'
                      : 'danger'
                }
                style={{ height: '6px' }}
              />
            </div>

            <Badge bg="info" className="me-1">
              <FaMapPin className="me-1" /> {displayData.locationsVisited} locations
            </Badge>
          </Col>
        </Row>
      </Card.Body>
    </Card>
  );
};

const LIBRARIES = ['places', 'geometry'];
const GMAP_KEY = 'AIzaSyD1Uvzt4qmx6O7DcUf0gH3DfrLssx_ARfc';

const calcHeading = (lat1, lng1, lat2, lng2) => {
  const dLng = (lng2 - lng1) * Math.PI / 180;
  const y = Math.sin(dLng) * Math.cos(lat2 * Math.PI / 180);
  const x = Math.cos(lat1 * Math.PI / 180) * Math.sin(lat2 * Math.PI / 180) -
    Math.sin(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) * Math.cos(dLng);
  return (Math.atan2(y, x) * 180 / Math.PI + 360) % 360;
};

const EmployeeLiveTracking = ({ employee, autoRefresh, selectedDate, staffGeoList, staffGeoSuccess }) => {
  const { isLoaded, loadError } = useLoadScript({
    googleMapsApiKey: GMAP_KEY,
    libraries: LIBRARIES,
  });

  const mapRef = useRef(null);
  const posRef = useRef(null);
  const [latestPos, setLatestPos] = useState(null);
  const [routeCoords, setRouteCoords] = useState([]);
  const [heading, setHeading] = useState(0);

  // Use DB geo locations as initial position + route
  useEffect(() => {
    if (!staffGeoSuccess || !staffGeoList) return;

    // staffGeoList is { count, records: { geoLocation: [...] } }
    const geoLocationArr = staffGeoList.records?.geoLocation || [];
    if (geoLocationArr.length === 0) return;

    const sorted = [...geoLocationArr].sort((a, b) => (a.recordCreatedAt || a.createdAt) - (b.recordCreatedAt || b.createdAt));
    const coords = sorted
      .map(p => {
        const lat = parseFloat(p.latitude);
        const lng = parseFloat(p.longitude);
        return !isNaN(lat) && !isNaN(lng) ? { lat, lng } : null;
      })
      .filter(Boolean);
    setRouteCoords(coords);

    if (coords.length > 0 && !posRef.current) {
      const latest = coords[coords.length - 1];
      posRef.current = latest;
      setLatestPos(latest);
      if (autoRefresh && mapRef.current) {
        mapRef.current.panTo(latest);
      }
    }
  }, [staffGeoSuccess, staffGeoList]);

  // Track position changes from socket (employee.latestGeoPoint)
  useEffect(() => {
    const g = employee.latestGeoPoint;
    if (!g?.latitude || !g?.longitude) return;

    const newPos = { lat: parseFloat(g.latitude), lng: parseFloat(g.longitude) };
    const prev = posRef.current;

    if (prev && (prev.lat !== newPos.lat || prev.lng !== newPos.lng)) {
      setHeading(calcHeading(prev.lat, prev.lng, newPos.lat, newPos.lng));
    }

    if (!prev || prev.lat !== newPos.lat || prev.lng !== newPos.lng) {
      posRef.current = newPos;
      setLatestPos(newPos);
      setRouteCoords(prevCoords => [...prevCoords, newPos]);
      if (autoRefresh && mapRef.current) {
        mapRef.current.panTo(newPos);
      }
    }
  }, [employee, employee.latestGeoPoint, autoRefresh]);

  if (loadError) {
    return <div className="text-center py-5 text-danger">Error loading map</div>;
  }

  if (!isLoaded) {
    return <div className="text-center py-5"><Spinner animation="border" /></div>;
  }

  const center = latestPos || { lat: 10.9601, lng: 78.0766 };

  return (
    <Row>
      <Col xs={12}>
        <Card>
          <Card.Header className="bg-primary text-white d-flex justify-content-between align-items-center">
            <div>
              <h5 className="mb-0"><FaUser className="me-2" /> {employee.name} — Live Tracking</h5>
              <small className="opacity-75">
                Employee ID: {employee.employeeId} | {moment(selectedDate).format('DD-MMM-YYYY')}
                {autoRefresh && <span className="ms-2 badge bg-success">LIVE</span>}
              </small>
            </div>
            {latestPos && (
              <Badge bg="light" text="dark" className="fs-6">
                {latestPos.lat.toFixed(6)}, {latestPos.lng.toFixed(6)}
              </Badge>
            )}
          </Card.Header>
          <Card.Body className="p-0" style={{ height: '550px' }}>
            <GoogleMap
              mapContainerStyle={{ width: '100%', height: '100%' }}
              center={center}
              zoom={16}
              onLoad={(map) => { mapRef.current = map; }}
              options={{
                streetViewControl: true,
                mapTypeControl: true,
                zoomControl: true,
                styles: [{ featureType: 'poi', elementType: 'labels', stylers: [{ visibility: 'off' }] }],
              }}
            >
              {/* {routeCoords.length > 1 && (
                <Polyline
                  path={routeCoords}
                  options={{
                    strokeColor: '#3B82F6',
                    strokeOpacity: 0.7,
                    strokeWeight: 3,
                  }}
                />
              )} */}
              {latestPos && (
                <Marker
                  position={latestPos}
                  icon={{
                    path: 'M 0,-22 L 12,18 L 0,8 L -12,18 Z',
                    fillColor: '#10B981',
                    fillOpacity: 1,
                    strokeColor: '#fff',
                    strokeWeight: 2,
                    rotation: heading,
                    scale: 1,
                    anchor: new window.google.maps.Point(0, 0),
                  }}
                />
              )}
            </GoogleMap>
          </Card.Body>
        </Card>
      </Col>

    </Row>
  );
};

